package com.termux.app.workspace;
import org.json.*;import org.junit.*;import static org.junit.Assert.*;
import android.app.Application;import org.junit.runner.RunWith;import org.robolectric.RobolectricTestRunner;import org.robolectric.annotation.Config;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class LocalAiListContextTest {
 JSONObject listing(int n)throws Exception{JSONArray es=new JSONArray();for(int i=0;i<n;i++)es.put(new JSONObject().put("path","/sdcard/Download/Long file name "+i+".txt").put("name","Long file name "+i+".txt").put("type","file").put("modifiedMillis",1000-i).put("size",i).put("match","exact"));return new JSONObject().put("checkedPath","/sdcard/Download").put("matched",n+2).put("truncated",true).put("entries",es);}
 @Test public void fullRequestedListPreservesAllRowsOrderMetadataAndArchiveWithoutBrokenJson()throws Exception{JSONObject data=listing(200);String original="exit=0\n"+data;String out=LocalAiListContext.preview(new JSONObject().put("tool","list"),original);JSONObject v=LocalAiSearchResult.parse(out);assertNotNull(v);assertEquals(200,v.getJSONArray("rows").length());assertEquals(202,v.getInt("matched"));assertTrue(v.getBoolean("truncated"));assertEquals("/sdcard/Download/Long file name 0.txt",v.getJSONArray("rows").getJSONArray(0).getString(0));assertEquals(1000,v.getJSONArray("rows").getJSONArray(0).getInt(3));assertEquals(original,"exit=0\n"+data);assertTrue(out.length()<original.length());}
 @Test public void errorsReadTextAndMalformedListingsAreNotInterpretedAsFileLists()throws Exception{String error="exit=2\nACCESS_DENIED";assertEquals(error,LocalAiListContext.compact(new JSONObject().put("tool","list"),error));String data="exit=0\n"+listing(1);assertEquals(data,LocalAiListContext.compact(new JSONObject().put("tool","read"),data));assertEquals("exit=0\n{\"entries\":[3]}",LocalAiListContext.compact(new JSONObject().put("tool","list"),"exit=0\n{\"entries\":[3]}"));}
 @Test public void commonAgentUsesCompactContextButSavesFullResultForAllModelFamilies()throws Exception{for(String model:new String[]{"qwen35-2b","gemma4-e2b","gemma4-e4b","import-custom"}){LocalAiAgentTest.Fixture f=new LocalAiAgentTest.Fixture();f.p.localModel=model;String result="exit=0\n"+listing(2);int[] n={0};LocalAiAgent.run(f.p,f.history,f.cancelled,(h,s,o)->{if(n[0]++==0){assertTrue(s.contains("\\\"limit\\\":1")||s.contains("\"limit\":1"));return new LocalAiAgent.Generation("{\"tool\":\"list\",\"path\":\"/sdcard/Download\"}","eos");}String text=h.getJSONObject(h.length()-1).getString("text");assertTrue(text.contains("\"columns\""));assertFalse(text.contains("\"entries\""));return new LocalAiAgent.Generation("done","eos");},r->result,r->true,f,t->{});assertEquals(result,f.history.getJSONObject(2).getString("text"));assertTrue(f.history.getJSONObject(1).getString("toolOutput").contains("\"entries\""));}}
}
